// The launcher's embedded fonts and icon (bytes generated by embed.cmake; see CMakeLists.txt).
#pragma once

#include <cstddef>
#include <cstdint>

#include "ui/include/trg/launcher.h"

namespace dcp {

extern const uint8_t kFontInterRegular[];
extern const size_t kFontInterRegularSize;
extern const uint8_t kFontInterSemiBold[];
extern const size_t kFontInterSemiBoldSize;
extern const uint8_t kFontInterBold[];
extern const size_t kFontInterBoldSize;
extern const uint8_t kFontCinzelBold[];
extern const size_t kFontCinzelBoldSize;
extern const uint8_t kFontJetBrainsMono[];
extern const size_t kFontJetBrainsMonoSize;
extern const uint8_t kLauncherIcon[];  // app-icon-128.png
extern const size_t kLauncherIconSize;

// Inter (body), Cinzel (titles) and JetBrains Mono (values) at the mockup's 13 px base size.
inline trg::Fonts LoadLauncherFonts() {
    trg::FontSet set;
    set.regular = {kFontInterRegular, kFontInterRegularSize};
    set.semibold = {kFontInterSemiBold, kFontInterSemiBoldSize};
    set.bold = {kFontInterBold, kFontInterBoldSize};
    set.heading = {kFontCinzelBold, kFontCinzelBoldSize};
    set.mono = {kFontJetBrainsMono, kFontJetBrainsMonoSize};
    return trg::LoadFonts(set, 13.0f);
}

} // namespace dcp
